WITH sales_detail AS ( SELECT ws.ws_sold_date_sk, p.wp_type, i.i_category, ws.ws_ext_sales_price, ws.ws_quantity FROM web_sales ws JOIN web_page p ON ws.ws_web_page_sk = p.wp_web_page_sk JOIN item i ON ws.ws_item_sk = i.i_item_sk ), daily_page_sales AS ( SELECT ws_sold_date_sk, wp_type, SUM(ws_ext_sales_price) AS daily_sales, SUM(ws_quantity) AS daily_qty, COUNT(*) AS transaction_cnt FROM sales_detail GROUP BY ws_sold_date_sk, wp_type ), category_sales AS ( SELECT ws_sold_date_sk, wp_type, i_category, SUM(ws_ext_sales_price) AS cat_sales FROM sales_detail GROUP BY ws_sold_date_sk, wp_type, i_category ), category_popular AS ( SELECT ws_sold_date_sk, wp_type, i_category, cat_sales, ROW_NUMBER() OVER (PARTITION BY ws_sold_date_sk, wp_type ORDER BY cat_sales DESC) AS cat_rank FROM category_sales ) SELECT dps.ws_sold_date_sk, dps.wp_type, dps.daily_sales, SUM(dps.daily_sales) OVER (PARTITION BY dps.wp_type ORDER BY dps.ws_sold_date_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_sales, AVG(dps.daily_sales) OVER (PARTITION BY dps.wp_type ORDER BY dps.ws_sold_date_sk ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg_7d, CASE WHEN dps.daily_sales >= 100000 THEN 'Very High' WHEN dps.daily_sales >= 50000 THEN 'High' WHEN dps.daily_sales >= 20000 THEN 'Medium' ELSE 'Low' END AS sales_volume_category, cp.i_category AS top_category FROM daily_page_sales dps LEFT JOIN category_popular cp ON dps.ws_sold_date_sk = cp.ws_sold_date_sk AND dps.wp_type = cp.wp_type AND cp.cat_rank = 1 ORDER BY dps.wp_type, dps.ws_sold_date_sk DESC LIMIT 100
